catalog=['# Daily Gen6 — soukromý katalog 100 kandidátních desek','','5. 10. 2026. Výroba a nezávislé technické i AI redakční přijetí jsou dokončené. Uživatel obsah dosud neschválil; není nasazen. Tuto tabulku ani server-pack nezveřejňovat.','','| Datum | Den | Obtížnost | Deska | Cílová slova | Obsahový hash |','|---|---|---|---|---|---|']
csvfile=io.StringIO();writer=csv.writer(csvfile);writer.writerow(['dailyDate','weekday','difficulty','puzzleId','rows','cols','wordCount','words','contentHash'])
sch=json.loads((P/'schedule.json').read_text());hashes={x['puzzleId']:x['contentHash'] for x in sch['bindings']}
