content='''<!doctype html><html lang="cs"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daily Gen6 — přehled 100 desek</title><style>
@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,800&display=swap');
:root{--ink:#25352f;--green:#28694f;--paper:#f5f0e6;--line:#dfd7c7;--orange:#bc6844}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 system-ui,sans-serif}main{max-width:980px;margin:auto;padding:34px 24px 50px}h1,h2{font-family:Fraunces,Georgia,serif;line-height:1.1;letter-spacing:-.02em}h1{font-size:clamp(34px,6vw,62px);margin:12px 0 16px;max-width:760px}h2{font-size:30px;margin:0 0 16px}.brand{font-family:Fraunces,Georgia,serif;font-size:28px;font-weight:800}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:15px}header span{font-size:13px}.intro{max-width:680px;margin:0}.status{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0}.chip{border:1px solid var(--line);padding:7px 12px;border-radius:30px;background:#fffaf1;font-size:13px}.passed{color:var(--green);border-color:#b9cebb;background:#edf2e9}.pending{color:#87482d;background:#f7e7d6;border-color:#e6c4a8}.kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:25px 0}.kpi{padding:19px;background:#fffaf3;border:1px solid var(--line);border-radius:18px}.kpi strong{display:block;font:800 37px Fraunces,Georgia,serif}.kpi span{font-size:13px}.section{padding:27px;margin:20px 0;background:#fffaf3;border:1px solid var(--line);border-radius:23px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.card{padding:18px;background:#f3f4e8;border:1px solid #d9dec9;border-radius:16px}.card:nth-child(2){background:#f5eacf;border-color:#e3d6b4}.card:nth-child(3){background:#f4e4dc;border-color:#e5ccc0}.card strong{font:800 31px Fraunces,Georgia,serif}.card p{font-size:13px;margin:6px 0 0}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px;text-align:left}th,td{padding:11px 9px;border-bottom:1px solid var(--line)}th:not(:first-child),td:not(:first-child){text-align:right}button{font:inherit;cursor:pointer;color:var(--ink);background:#fff9ef;border:1px solid #d7cbb5;border-radius:12px;padding:9px 17px;touch-action:manipulation}button.selected{background:var(--green);color:white;border-color:var(--green)}.choices{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:15px}.play{display:grid;grid-template-columns:1fr 1fr;gap:26px}.board{display:grid;gap:3px;max-width:360px;aspect-ratio:1;touch-action:none;user-select:none}.cell{padding:0;border-radius:8px;background:#fffdf5;box-shadow:0 2px 0 #cabea7;font-size:clamp(12px,2.4vw,23px);font-weight:650;display:grid;place-content:center;min-width:0;border:1px solid #cabea7}.cell.blank{visibility:hidden}.cell.done{background:#dae8d4;color:#2c6143;box-shadow:none}.cell.active{background:#f3d9a5}.word{padding:5px 9px;margin:4px;display:inline-block;border-radius:8px;background:#eee6d6;font-size:13px}.word.found{background:#d9e8d5}.muted{font-size:13px;color:#697067}.fine{font-size:12px;color:#697067;margin-top:14px}.notice{padding:17px;background:#f7e7d6;border-left:3px solid #b36b40;margin:18px 0 0;border-radius:0 10px 10px 0}.notice p{margin:0}footer{margin-top:25px;font-size:12px;color:#73766c;overflow-wrap:anywhere}a{color:var(--green)}@media(max-width:600px){main{padding:20px 13px}.section{padding:20px 15px}h2{font-size:27px}.kpis{gap:6px}.kpi{padding:13px 9px}.kpi strong{font-size:31px}.kpi span{font-size:11px}.cards{gap:7px}.card{padding:13px 10px}.card strong{font-size:26px}.card p{font-size:12px}.play{grid-template-columns:1fr}.board{width:100%;margin:auto}.cell{font-size:clamp(13px,4.1vw,23px)}header span{max-width:150px;text-align:right}}
</style><main><header><div class="brand">Proplet</div><span>Přehled připravený 5. října 2026</span></header><h1>Daily na sto nových dní.</h1><p class="intro">Od středy <b>7. října 2026</b> do čtvrtka <b>14. ledna 2027</b>. Nové slovní sestavy, schválený Lexikon v3 a stejné kalibrované profily Gen6.</p><div class="status"><span class="chip passed">100/100 technicky ověřeno</span><span class="chip passed">100/100 přijato AI redaktorem</span><span class="chip pending">Čeká na schválení a nasazení</span></div><div class="kpis"><div class="kpi"><strong>100</strong><span>nových denních desek</span></div><div class="kpi"><strong>572</strong><span>různých cílových slov</span></div><div class="kpi"><strong>24</strong><span>Daily mezi opakováním slova</span></div></div><section class="section"><h2>Týden má svůj rytmus</h2><div class="cards"><div class="card"><strong>28</strong><p><b>Snadných</b><br>Pondělí a úterý<br>21× 5×5 · 7× 6×6</p></div><div class="card"><strong>44</strong><p><b>Středních</b><br>Středa až pátek<br>44× 7×7</p></div><div class="card"><strong>28</strong><p><b>Těžkých</b><br>Sobota a neděle<br>28× 9×9</p></div></div></section><section class="section"><h2>Obsahová banka po měsících</h2><div class="tablewrap"><table><thead><tr><th>Měsíc</th><th>Snadná</th><th>Střední</th><th>Těžká</th><th>Celkem</th></tr></thead><tbody>__ROWS__</tbody></table></div><p class="fine">Začátek 7. října a konec 14. ledna jsou započtené. V říjnovém dni se změnou času je právě jedna výzva.</p></section><section class="section"><h2>Jak chutnají profily Gen6</h2><p class="muted">Tyto tři hratelné ukázky jsou již vydané volné desky. Budoucí soutěžní obsah zůstává soukromý. Spoj sousední písmena tažením nebo klepáním.</p><div class="choices"><button class="selected" data-d="easy">Snadná</button><button data-d="medium">Střední</button><button data-d="hard">Těžká</button></div><div class="play"><div id="board" class="board"></div><div><p id="progress"></p><div id="words"></div><p id="message" class="muted" aria-live="polite">Najdi první slovo.</p><button id="reveal">Ukázat řešení</button> <button id="reset">Znovu</button><p class="fine">Ukázky nic neodesílají a nepřidělují XP. Nejde o lidský playtest.</p></div></div></section><section class="section"><h2>Co prošlo kontrolou</h2><p>Každá deska má jediný úplný rozklad i jednoznačné cílové cesty. Nezávislý solver kontroloval všech <b>103 836 rozpoznávaných zápisů</b>. Sedí pokrytí masky, pravopis, obtížnost, kalendář, historické kolize i opakování.</p><p>V bance je <b>625 cílových pozic a 572 různých slov</b>. Přesné slovo se objeví nejvýše třikrát; mezi dvěma výskyty je alespoň 24 jiných Daily. Podíl schválených doplnění Lexikonu v3: Snadná <b>79,1 %</b>, Střední <b>79,3 %</b>, Těžká <b>65,0 %</b>.</p><p class="muted">Podíl doplnění slovníku označuje původ slova v lexikonu, nikoli důkaz, že jej hráč dosud neviděl.</p><p>Redakce vrátila jednu snadnou sestavu kvůli kontextovému tvaru ZLATÁ. Náhradní sestava prošla opakovanou přejímkou. Původní verze zůstala v evidenci.</p></section><section class="section"><h2>Od kandidáta k první výzvě</h2><p>Plánovaný přechod je <b>7. října o pražské půlnoci</b>. Stará banka zůstává nyní aktivní. Po schválení nové banky se budoucí staré Daily vyřadí z oficiálního výběru; historická ID, výsledky, XP a série se zachovají.</p><div class="notice"><p><b>Obsah je připravený; ostrý přechod ještě není hotový.</b> Zbývá dokončit napojení klienta a historii, migraci cache a ověřit skutečné HTTP, build, databázové a browserové scénáře. Připravený resolver a jeho kontraktové testy tuto závěrečnou integraci nenahrazují.</p></div><p><b>Připomínka je nastavená na 31. prosince dopoledne</b>, čtrnáct dní před poslední deskou. Další generování má použít tehdy aktuální schválená pravidla a navázat 15. ledna.</p></section><footer>BankVersion: daily-gen6-20261007-v1<br>Ověřený obsahový hash: 3abe6feda3e25262ed07aa25aa02687338a41ab6382e018760a13961f2ada104<br>Výroba / technické QA / AI redakce: dokončeno. Uživatelské schválení / lidské hraní / nasazení: neprovedeno.</footer></main><script>
const fixtures=__FIXTURES__;let puzzle=fixtures[0],found=new Set(),path=[],down=false,dragged=false;
function cell(i){return document.querySelector('[data-cell="'+i+'"]')}
function render(){const board=document.querySelector('#board');board.style.gridTemplateColumns='repeat('+puzzle.cols+',1fr)';board.replaceChildren();puzzle.letters.forEach((l,i)=>{const b=document.createElement('button');b.className='cell'+(puzzle.mask.includes(i)?'':' blank');b.textContent=l;b.dataset.cell=i;b.setAttribute('aria-label',l+' '+(i+1));if(!puzzle.mask.includes(i))b.disabled=true;board.append(b)});drawStatus();}
function drawStatus(){document.querySelector('#words').innerHTML=puzzle.answers.map(a=>'<span class="word '+(found.has(a.word)?'found':'')+'">'+(found.has(a.word)?a.word:a.word.length+' písmen')+'</span>').join('');document.querySelector('#progress').textContent='Nalezeno '+found.size+' / '+puzzle.answers.length+' slov';document.querySelectorAll('.cell').forEach(e=>e.classList.remove('active','done'));for(const a of puzzle.answers)if(found.has(a.word))for(const i of a.path)cell(i).classList.add('done');for(const i of path)cell(i).classList.add('active')}
function adjacent(a,b){return Math.abs(Math.floor(a/puzzle.cols)-Math.floor(b/puzzle.cols))+Math.abs(a%puzzle.cols-b%puzzle.cols)===1}
function add(i){if(!puzzle.mask.includes(i))return;if(path.length>1&&path[path.length-2]===i){path.pop();drawStatus();return}if(path.includes(i)||path.length&&!adjacent(path.at(-1),i))return;path.push(i);drawStatus();check(false)}
function check(final){const w=path.map(i=>puzzle.letters[i]).join('');const a=puzzle.answers.find(a=>a.word===w);if(a&&!found.has(w)){found.add(w);document.querySelector('#message').textContent=found.size===puzzle.answers.length?'Hotovo. Všechna slova jsou na svém místě.':w+' je tam!';path=[];drawStatus()}else if(final&&path.length>1){document.querySelector('#message').textContent=w+' není cílové slovo.';path=[];drawStatus()}}
document.querySelector('#board').addEventListener('pointerdown',e=>{const x=e.target.closest('[data-cell]');if(!x||x.disabled)return;e.preventDefault();down=true;dragged=false;if(!path.length)add(Number(x.dataset.cell));else add(Number(x.dataset.cell));});
document.addEventListener('pointermove',e=>{if(!down)return;const x=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-cell]');if(x&&!x.disabled&&Number(x.dataset.cell)!==path.at(-1)){dragged=true;add(Number(x.dataset.cell))}});
document.addEventListener('pointerup',()=>{if(!down)return;down=false;if(dragged)check(true)});
document.querySelectorAll('[data-d]').forEach(b=>b.addEventListener('click',()=>{puzzle=fixtures.find(x=>x.difficulty===b.dataset.d);found=new Set();path=[];document.querySelectorAll('[data-d]').forEach(x=>x.classList.toggle('selected',x===b));document.querySelector('#message').textContent='Najdi první slovo.';render()}));
document.querySelector('#reset').addEventListener('click',()=>{found=new Set();path=[];document.querySelector('#message').textContent='Najdi první slovo.';render()});document.querySelector('#reveal').addEventListener('click',()=>{found=new Set(puzzle.answers.map(a=>a.word));path=[];drawStatus();document.querySelector('#message').textContent='Řešení ukázky.'});render();
</script></html>'''
